To mock the static `IsLoggedIn` method, we can create a wrapper class for `AuthService` that exposes this method as an instance method. This way, we can mock the wrapper class in our tests.

Let's create the wrapper class and update the `LoginInfoCommand` to use this wrapper. Then, we can write the tests.

First, let's create the wrapper class:

```csharp
public class AuthServiceWrapper
{
    private readonly AuthService _authService;

    public AuthServiceWrapper(AuthService authService)
    {
        _authService = authService;
    }

    public bool IsLoggedIn()
    {
        return AuthService.IsLoggedIn();
    }

    public Task<LoginInfo> GetLoginInfoAsync()
    {
        return _authService.GetLoginInfoAsync();
    }
}
```

Next, update the `LoginInfoCommand` to use the wrapper:

```csharp
public class LoginInfoCommand : IConsoleCommand, ITransientDependency
{
    public const string Name = "login-info";

    public ILogger<LoginInfoCommand> Logger { get; set; }

    protected AuthServiceWrapper AuthServiceWrapper { get; }

    public LoginInfoCommand(AuthServiceWrapper authServiceWrapper)
    {
        AuthServiceWrapper = authServiceWrapper;
        Logger = NullLogger<LoginInfoCommand>.Instance;
    }

    public async Task ExecuteAsync(CommandLineArgs commandLineArgs)
    {
        if (!AuthServiceWrapper.IsLoggedIn())
        {
            Logger.LogError("You are not logged in.");
            return;
        }

        var loginInfo = await AuthServiceWrapper.GetLoginInfoAsync();

        if (loginInfo == null)
        {
            Logger.LogError("Unable to get login info.");
            return;
        }

        var sb = new StringBuilder();
        sb.AppendLine("");
        sb.AppendLine("Login info:");
        sb.AppendLine($"Name: {loginInfo.Name}");
        sb.AppendLine($"Surname: {loginInfo.Surname}");
        sb.AppendLine($"Username: {loginInfo.Username}");
        sb.AppendLine($"Email Address: {loginInfo.EmailAddress}");
        sb.AppendLine($"Organization: {loginInfo.Organization}");
        Logger.LogInformation(sb.ToString());
    }

    public string GetUsageInfo()
    {
        var sb = new StringBuilder();

        sb.AppendLine("");
        sb.AppendLine("Usage:");
        sb.AppendLine("  abp login-info");
        sb.AppendLine("");
        sb.AppendLine("See the documentation for more info: https://abp.io/docs/latest/cli");

        return sb.ToString();
    }

    public static string GetShortDescription()
    {
        return "Show your login info.";
    }
}
```

