    public async Task ExecuteAsync_LoggedInAndHasLoginInfo_LogsLoginInfo()
    {
        // Arrange
        var authServiceMock = new Mock<AuthService>(null, null, null, null, null, null);
        var authServiceWrapper = new AuthServiceWrapper(authServiceMock.Object);
        var authServiceWrapperMock = new Mock<AuthServiceWrapper>(authServiceWrapper);
        authServiceWrapperMock.Setup(x => x.IsLoggedIn()).Returns(true);
        var loginInfo = new LoginInfo
        {
            Name = "John",
            Surname = "Doe",
            Username = "johndoe",
            EmailAddress = "john.doe@example.com",
            Organization = "Example Org"
        };
        authServiceWrapperMock.Setup(x => x.GetLoginInfoAsync()).ReturnsAsync(loginInfo);
        var loggerMock = new Mock<ILogger<LoginInfoCommand>>();
        var command = new LoginInfoCommand(authServiceWrapperMock.Object)
        {
            Logger = loggerMock.Object
        };

        // Act
        await command.ExecuteAsync(new CommandLineArgs());

        // Assert
        loggerMock.Verify(
            x => x.LogInformation(It.Is<string>(s => s.Contains("Login info:"))),
            Times.Once);
    }
